# Python script to generate 365+ authentic Prophetic reminders
import json

hadiths = []

def add(text, source, category):
    hadiths.append({
        "id": len(hadiths) + 1,
        "text": text.strip(),
        "source": source.strip(),
        "category": category.strip()
    })

