# Write to src/data/hadithCollection.js
js_content = f"""/**
 * Comprehensive collection of {len(hadiths)} authentic Prophetic reminders bundled with Iftyar.
 * Covers Ramadan, Fasting, Salah, Character, Dhikr, Du'a, Charity, Patience, and Righteous Deeds.
 * Each entry includes verified text, primary canonical source, and thematic category.
 */

export const HADITH_CATEGORIES = [
  'All',
  'Ramadan & Fasting',
  'Prayer & Salah',
  'Dhikr & Remembrance',
  'Charity & Generosity',
  'Character & Manners',
  'Patience & Gratitude',
  'Repentance & Mercy',
  'Family & Kinship',
  'Knowledge & Wisdom',
  'Righteous Deeds',
]

export const HADITH_COLLECTION = {json.dumps(hadiths, indent=2, ensure_ascii=False)}

/**
 * Returns a random Hadith from the collection.
 */
export function getRandomHadith(category = null) {{
  const pool = category && category !== 'All'
    ? HADITH_COLLECTION.filter((h) => h.category === category)
    : HADITH_COLLECTION

  const list = pool.length > 0 ? pool : HADITH_COLLECTION
  const index = Math.floor(Math.random() * list.length)
  return list[index]
}}

/**
 * Returns a stable Hadith of the day based on the calendar day of the year.
 */
export function getHadithOfTheDay(date = new Date()) {{
  const start = new Date(date.getFullYear(), 0, 0)
  const diff = date - start
  const oneDay = 1000 * 60 * 60 * 24
  const dayOfYear = Math.floor(diff / oneDay)
  const index = Math.abs(dayOfYear) % HADITH_COLLECTION.length
  return HADITH_COLLECTION[index]
}}

/**
 * Returns a Hadith by its specific numerical ID.
 */
export function getHadithById(id) {{
  return HADITH_COLLECTION.find((h) => h.id === id) || HADITH_COLLECTION[0]
}}
"""

with open("src/data/hadithCollection.js", "w", encoding="utf-8") as f:
    f.write(js_content)

print("Successfully wrote src/data/hadithCollection.js!")
